refused_program.body:
set -e
git merge --no-edit {upstream_remote}/{upstream_branch} || true
unmerged=$(git diff --name-only --diff-filter=U -z | tr '\0' '\n')
if [ -n "$unmerged" ]; then
  tmp=$(mktemp -d)
  printf '%s\n' "$unmerged" | while IFS= read -r f; do
    [ -n "$f" ] || continue
    git show ":1:$f" > "$tmp/base" 2>/dev/null || : > "$tmp/base"
    git show ":2:$f" > "$tmp/ours" 2>/dev/null || : > "$tmp/ours"
    git show ":3:$f" > "$tmp/theirs" 2>/dev/null || : > "$tmp/theirs"
    git merge-file -p --diff3 -L ours -L base -L theirs "$tmp/ours" "$tmp/base" "$tmp/theirs" > "$tmp/merged" || true
    awk '
    function key(s,   t, i) {
      t = s
      sub(/^[ \t]+/, "", t)
      i = index(t, "=")
      if (i > 0) {
        t = substr(t, 1, i - 1)
        sub(/[ \t]+$/, "", t)
        return t
      }
      return ""
    }
    function emit(   i, k, bset, tset, oset, skeys) {
      split("", bset); split("", tset); split("", oset); split("", skeys)
      for (i = 1; i <= n_b; i++) bset[B[i]] = 1
      for (i = 1; i <= n_o; i++) oset[O[i]] = 1
      for (i = 1; i <= n_t; i++) {
        tset[T[i]] = 1
        if ((T[i] in bset) && !(T[i] in oset)) continue
        print T[i]
        k = key(T[i])
        if (k != "") skeys[k] = 1
      }
      for (i = 1; i <= n_o; i++) {
        if ((O[i] in bset) || (O[i] in tset)) continue
        k = key(O[i])
        if (k != "" && (k in skeys)) continue
        print O[i]
        if (k != "") skeys[k] = 1
      }
    }
    st == 0 && /^<<<<<<< / { st = 1; n_o = 0; n_b = 0; n_t = 0; next }
    st == 1 && /^\|\|\|\|\|\|\| / { st = 2; next }
    (st == 1 || st == 2) && /^=======$/ { st = 3; next }
    st == 3 && /^>>>>>>> / { emit(); st = 0; next }
    st == 1 { O[++n_o] = $0; next }
    st == 2 { B[++n_b] = $0; next }
    st == 3 { T[++n_t] = $0; next }
    { print }
    ' "$tmp/merged" > "$tmp/resolved"
    cp "$tmp/resolved" "$f"
    git add -- "$f"
  done
  rm -rf "$tmp"
  git commit --no-edit
fi
